package com.quincaisoft.identity.web;
import com.quincaisoft.identity.api.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/v1/identity") @PreAuthorize("hasAnyAuthority('identity:manage','SCOPE_identity:manage')") public class IdentityController {private final IdentityService service;public IdentityController(IdentityService service){this.service=service;}@GetMapping("/members")public List<IdentityService.Member> members(){return service.members();}@GetMapping("/changes")public List<IdentityService.Change> changes(){return service.changes();}@PostMapping("/changes")public IdentityService.Change request(@RequestHeader("Idempotency-Key")UUID operation,@RequestBody IdentityService.Request input){if(!operation.equals(input.operationId()))throw new IllegalArgumentException("Operation IDs must match");return service.request(input);}record Approval(UUID operationId,long version){}@PostMapping("/changes/{id}/approve")public IdentityService.Change approve(@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID operation,@RequestBody Approval input){if(!operation.equals(input.operationId()))throw new IllegalArgumentException("Operation IDs must match");return service.approve(id,operation,input.version());}}
